cat << 'EOF' > parse.py
import csv
import re

elements_allowed = {"O", "Cu", "Ba", "Sr", "Y", "Ca", "La", "Bi", "Fe", "Nb", "C", "Pr", "As", "B", "Pb", "Ce", "Mo", "V", "Zn", "Ni"}

def parse_composition(comp):
    matches = re.findall(r'([A-Z][a-z]*)(\d*\.?\d*)', comp)
    parsed = {}
    for el, num in matches:
        if num == '':
            parsed[el] = parsed.get(el, 0) + 1.0
        else:
            parsed[el] = parsed.get(el, 0) + float(num)
    return parsed

with open('b3_supercon_data.csv', 'r') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

valid_rows = []
for row in rows:
    comp = row['composition']
    parsed = parse_composition(comp)
    if all(el in elements_allowed for el in parsed.keys()) and len(parsed) <= 4:
        valid_rows.append((comp, float(row['target']), parsed))

valid_rows.sort(key=lambda x: x[1], reverse=True)

for i in range(10):
    if i < len(valid_rows):
        comp, target, parsed = valid_rows[i]
        total = sum(parsed.values())
        fractions = {el: val/total for el, val in parsed.items()}
        print(f"{comp}: {target}, {fractions}")
EOF
python3 parse.py

